/* ---------- dấu thanh kiểu cũ / kiểu mới ---------- */
// Thứ tự thanh: huyền, sắc, hỏi, ngã, nặng.
const TONED: Record<string, string> = {
  o: 'òóỏõọ', O: 'ÒÓỎÕỌ',
  u: 'ùúủũụ', U: 'ÙÚỦŨỤ',
  a: 'àáảãạ', A: 'ÀÁẢÃẠ',
  e: 'èéẻẽẹ', E: 'ÈÉẺẼẸ',
  y: 'ỳýỷỹỵ', Y: 'ỲÝỶỸỴ',
};

function toneOf(ch: string, base: string): number {
  return TONED[base].indexOf(ch);
}

/**
 * "hòa" và "hoà", "thủy" và "thuỷ", "khỏe" và "khoẻ" đều được chấp nhận trong chính tả tiếng Việt.
 * Đưa về một kiểu (dấu đặt trên nguyên âm sau) để so sánh. Chỉ đổi khi "oa/oe/uy" đứng cuối tiếng.
 */
export function unifyToneMarks(s: string): string {
  return s
    .replace(/([òóỏõọÒÓỎÕỌ])([aeAE])(?![\p{L}\p{M}])/gu, (_m, o: string, v: string) => {
      const lower = o === o.toLowerCase();
      const t = toneOf(o, lower ? 'o' : 'O');
      return (lower ? 'o' : 'O') + TONED[v][t];
    })
    .replace(/([ùúủũụÙÚỦŨỤ])([yY])(?![\p{L}\p{M}])/gu, (_m, u: string, y: string) => {
      const lower = u === u.toLowerCase();
      const t = toneOf(u, lower ? 'u' : 'U');
      return (lower ? 'u' : 'U') + TONED[y][t];
    });
}

/** Chuẩn hoá để so sánh: NFC, bỏ khoảng trắng đầu/cuối, gộp khoảng trắng, chữ thường (trừ khi phân biệt hoa/thường). */
export function normalizeText(s: string, caseSensitive = false): string {
  let t = (s ?? '').normalize('NFC').replace(/[\s ]+/g, ' ').trim();
  t = unifyToneMarks(t);
  return caseSensitive ? t : t.toLowerCase();
}

/* ---------- số ---------- */

/**
 * Các cách hiểu một chuỗi thành số. Học sinh Việt Nam viết "2,5" (dấu phẩy thập phân), "1.000" hoặc "1 000"
 * (dấu chấm / khoảng trắng phân nhóm nghìn). "1.000" mơ hồ nên trả về cả 1 và 1000.
 * Trả về [] nếu không phải số.
 */
export function parseNumberCandidates(input: string): number[] {
  let s = (input ?? '').normalize('NFC').replace(/[\s ]+/g, ' ').trim().replace(/−/g, '-');
  if (s.startsWith('+')) s = s.slice(1);
  if (!s) return [];
  const out: number[] = [];
  const add = (txt: string) => {
    const n = Number(txt);
    if (Number.isFinite(n) && !out.some((x) => x === n)) out.push(n);
  };
  if (/^-?\d+$/.test(s)) add(s);
  else if (/^-?\d*,\d+$/.test(s)) add(s.replace(',', '.'));
  else if (/^-?\d*\.\d+$/.test(s)) {
    add(s);
    if (/^-?\d{1,3}(\.\d{3})+$/.test(s)) add(s.replace(/\./g, ''));
  } else if (/^-?\d{1,3}(\.\d{3})+,\d+$/.test(s)) add(s.replace(/\./g, '').replace(',', '.'));
  else if (/^-?\d{1,3}( \d{3})+([.,]\d+)?$/.test(s)) add(s.replace(/ /g, '').replace(',', '.'));
  return out;
}

function numbersEqual(a: number[], b: number[]): boolean {
  return a.some((x) => b.some((y) => Math.abs(x - y) < 1e-9));
}

/** Bỏ dấu câu cuối mà trẻ hay gõ thêm ("con mèo." → "con mèo"). */
function stripTrailingPunct(s: string): string {
  return s.replace(/[\s.!?;:,…]+$/u, '');
}

/**
 * Câu trả lời có khớp một trong các đáp án chấp nhận không.
 * - So chữ sau normalizeText (và bỏ dấu câu cuối).
 * - Nếu cả hai đều là số: so theo giá trị ("2,5" == "2.5", "07" == "7", "1 000" == "1000").
 */
export function answersMatch(given: string, accepted: readonly string[], caseSensitive = false): boolean {
  const g = normalizeText(given ?? '', caseSensitive);
  if (!g) return false;
  const gLoose = stripTrailingPunct(g);
  const gNum = parseNumberCandidates(gLoose);
  for (const a of accepted ?? []) {
    const n = normalizeText(a ?? '', caseSensitive);
    if (!n) continue;
    if (n === g || stripTrailingPunct(n) === gLoose) return true;
    if (gNum.length) {
      const aNum = parseNumberCandidates(stripTrailingPunct(n));
      if (aNum.length && numbersEqual(gNum, aNum)) return true;
    }
  }
  return false;
}

/* ---------- đoạn văn có chỗ trống ---------- */

export type PassageSegment = { type: 'text'; text: string } | { type: 'blank'; id: string };

const BLANK_RE = /\{\{\s*([A-Za-z0-9_-]+)\s*\}\}/g;

/** Tách đoạn văn "Mẹ đi {{b1}} về." thành các đoạn chữ và chỗ trống. */
export function parseBlanks(passage: string): PassageSegment[] {
  const out: PassageSegment[] = [];
  const src = passage ?? '';
  let last = 0;
  BLANK_RE.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = BLANK_RE.exec(src)) !== null) {
    if (m.index > last) out.push({ type: 'text', text: src.slice(last, m.index) });
    out.push({ type: 'blank', id: m[1] });
    last = m.index + m[0].length;
  }
  if (last < src.length) out.push({ type: 'text', text: src.slice(last) });
  return out;
}

/** Id các chỗ trống theo thứ tự xuất hiện, không trùng. */
export function blankIds(passage: string): string[] {
  const ids: string[] = [];
  for (const s of parseBlanks(passage)) if (s.type === 'blank' && !ids.includes(s.id)) ids.push(s.id);
  return ids;
}
